    #[tokio::test]
    async fn http_reader_preserves_pipelined_requests() -> Result<()> {
        let listener = TcpListener::bind("127.0.0.1:0").await?;
        let address = listener.local_addr()?;
        let server = tokio::spawn(async move {
            let (stream, _) = listener.accept().await?;
            let mut connection = HttpConnection::new(stream);
            let first = connection
                .read_request()
                .await?
                .ok_or_else(|| anyhow!("first request missing"))?;
            let second = connection
                .read_request()
                .await?
                .ok_or_else(|| anyhow!("second request missing"))?;
            Ok::<_, anyhow::Error>((first, second))
        });
        let mut client = TcpStream::connect(address).await?;
        client
            .write_all(
                b"POST / HTTP/1.1\r\nHost: localhost\r\nContent-Length: 3\r\nConnection: keep-alive\r\n\r\nabcGET /rest/chaininfo.json HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n",
            )
            .await?;
        let (first, second) = server.await??;
        assert_eq!(first.method, "POST");
        assert_eq!(first.target, "/");
        assert_eq!(first.body, b"abc");
        assert!(first.keep_alive);
        assert_eq!(second.method, "GET");
        assert_eq!(second.target, "/rest/chaininfo.json");
        assert!(second.body.is_empty());
        assert!(!second.keep_alive);
        Ok(())
    }

    fn proof_transaction(tag: u8) -> Transaction {
        Transaction {
            version: Version::ONE,
            lock_time: LockTime::ZERO,
            input: vec![TxIn {
                previous_output: OutPoint::new(Txid::from_byte_array([tag; 32]), 0),
                script_sig: ScriptBuf::from_bytes(vec![0x00; 8]),
                sequence: bitcoin::Sequence::MAX,
                witness: Witness::default(),
            }],
            output: vec![TxOut {
                value: bitcoin::Amount::from_sat(u64::from(tag)),
                script_pubkey: ScriptBuf::from_bytes(vec![0x51]),
            }],
        }
    }

    #[test]
    fn mining_selection_reserves_coinbase_sigops() {
        let directory = tempfile::tempdir().unwrap();
        let chain = chain::ChainState::open(Network::Regtest, directory.path()).unwrap();
        let mut mempool = Mempool::new(Network::Regtest);

        let high_sigop_transaction = Transaction {
            version: Version::ONE,
            lock_time: LockTime::ZERO,
            input: vec![TxIn {
                previous_output: OutPoint::new(Txid::from_byte_array([1; 32]), 0),
                script_sig: ScriptBuf::new(),
                sequence: bitcoin::Sequence::MAX,
                witness: Witness::default(),
            }],
            output: vec![TxOut {
                value: Amount::from_sat(1),
                script_pubkey: ScriptBuf::from_bytes(vec![
                    bitcoin::blockdata::opcodes::all::OP_CHECKSIG.to_u8();
                    79_600
                ]),
            }],
        };
        let low_sigop_transaction = Transaction {
            version: Version::ONE,
            lock_time: LockTime::ZERO,
            input: vec![TxIn {
                previous_output: OutPoint::new(Txid::from_byte_array([2; 32]), 0),
                script_sig: ScriptBuf::new(),
                sequence: bitcoin::Sequence::MAX,
                witness: Witness::default(),
            }],
            output: vec![TxOut {
                value: Amount::from_sat(1),
                script_pubkey: ScriptBuf::from_bytes(vec![0x51]),
            }],
        };
        let high_sigop_id = high_sigop_transaction.compute_txid();
        let low_sigop_id = low_sigop_transaction.compute_txid();
        for transaction in [high_sigop_transaction, low_sigop_transaction] {
            mempool.insert_test_entry(crate::mempool::MempoolEntry {
                vsize: transaction.vsize() as u64,
                fee_sat: 1,
                added_at: 0,
                height: 0,
                transaction,
            });
        }

        let selected = filter_mining_transaction_ids(
            [high_sigop_id, low_sigop_id],
            &chain,
            &mempool,
            DEFAULT_COINBASE_OUTPUT_MAX_ADDITIONAL_SIGOPS,
        );
        assert_eq!(selected, vec![low_sigop_id]);
    }

