    #[test]
    fn raw_transaction_fee_and_burn_limits_validate_rpc_arguments() {
        assert_eq!(parse_max_fee_rate(None).unwrap(), Some(10_000_000));
        assert_eq!(
            parse_max_fee_rate(Some(&json!("0.1"))).unwrap(),
            Some(10_000_000)
        );
        assert_eq!(parse_max_fee_rate(Some(&json!(0))).unwrap(), None);
        assert!(parse_max_fee_rate(Some(&json!(-1))).is_err());
        assert!(parse_max_fee_rate(Some(&json!(1.1))).is_err());
        assert!(parse_max_fee_rate(Some(&json!("1"))).is_err());
        assert_eq!(max_fee_for_vsize(1, 101), 1);
        assert!(!exceeds_max_fee(1, 101, Some(1)));
        assert!(exceeds_max_fee(2, 101, Some(1)));
        assert!(!exceeds_max_feerate(31_200, 104, Some(300_000)));
        assert!(exceeds_max_feerate(31_200, 104, Some(299_999)));
        assert_eq!(parse_max_burn_amount(None).unwrap(), 0);
        assert_eq!(parse_max_burn_amount(Some(&json!(0.00000001))).unwrap(), 1);
        assert_eq!(
            parse_max_burn_amount(Some(&json!("0.00000001"))).unwrap(),
            1
        );

        let mut transaction = proof_transaction(8);
        transaction.output.push(TxOut {
            value: Amount::from_sat(1),
            script_pubkey: Builder::new()
                .push_opcode(OP_RETURN)
                .push_slice([1u8])
                .into_script(),
        });
        assert!(validate_burn_amount(&transaction, 0).is_err());
        assert!(validate_burn_amount(&transaction, 1).is_ok());

        transaction.output.push(TxOut {
            value: Amount::from_sat(1),
            script_pubkey: ScriptBuf::from_bytes(vec![0x4c]),
        });
        assert!(validate_burn_amount(&transaction, 0).is_err());

        transaction.output.push(TxOut {
            value: Amount::from_sat(1),
            script_pubkey: ScriptBuf::from_bytes(vec![0x51; MAX_SCRIPT_SIZE + 1]),
        });
        assert!(validate_burn_amount(&transaction, 0).is_err());

        let rejected = rejected_transaction_json(&transaction, &MempoolError::FeeRate);
        assert_eq!(rejected["reject-reason"], "mempool min fee not met");
        assert_eq!(
            rejected["reject-details"],
            "transaction fee rate is below the relay minimum"
        );
        let relay_rejected = rejected_transaction_json(&transaction, &MempoolError::MinRelayFee);
        assert_eq!(relay_rejected["reject-reason"], "min relay fee not met");
        let missing =
            rejected_transaction_json(&transaction, &MempoolError::MissingInput(OutPoint::null()));
        assert!(missing.get("reject-details").is_none());
    }

    #[test]
    fn rpc_reports_same_txid_different_witness_like_core() {
        let existing = proof_transaction(42);
        let existing_wtxid = existing.compute_wtxid();
        let mut submitted = existing.clone();
        submitted.input[0].witness = Witness::from_slice(&[vec![1u8]]);
        let mut mempool = Mempool::new(Network::Regtest);
        mempool.insert_test_entry(crate::mempool::MempoolEntry {
            transaction: existing.clone(),
            fee_sat: 1,
            vsize: 1,
            added_at: 1,
            height: 0,
        });

        let error = MempoolError::SameNonWitnessData(existing_wtxid);
        assert_eq!(
            mempool_reject_reason(&error),
            "txn-same-nonwitness-data-in-mempool"
        );
        let rejected = rejected_transaction_json(&submitted, &error);
        assert_eq!(
            rejected["reject-reason"],
            "txn-same-nonwitness-data-in-mempool"
        );
        let exact_rejected = rejected_transaction_json(&existing, &MempoolError::AlreadyPresent);
        assert_eq!(exact_rejected["reject-reason"], "txn-already-in-mempool");
        assert_eq!(exact_rejected["reject-details"], "txn-already-in-mempool");
        let excluded_ancestors = HashSet::new();
        let package = package_transaction_json(
            &submitted,
            &[submitted.clone()],
            &mempool,
            false,
            true,
            &excluded_ancestors,
        )
        .unwrap();
        assert_eq!(
            package,
            json!({
                "txid": submitted.compute_txid().to_string(),
                "other-wtxid": existing_wtxid.to_string(),
            })
        );

        let directory = tempfile::tempdir().unwrap();
        let chain = chain::ChainState::open(Network::Regtest, directory.path()).unwrap();
        let unprocessed = proof_transaction(43);
        let (candidate, result) =
            mempool.accept_package_for_test(&[existing.clone(), unprocessed.clone()], &chain);
        let Err(failure) = result else {
            panic!("expected the exact duplicate to fail package test acceptance");
        };
        assert_eq!(
            package_test_failure_json(
                &[existing.clone(), unprocessed.clone()],
                &candidate,
                failure,
            )
            .unwrap(),
            json!([
                {
                    "txid": existing.compute_txid().to_string(),
                    "wtxid": existing.compute_wtxid().to_string(),
                    "allowed": false,
                    "reject-reason": "txn-already-in-mempool",
                    "reject-details": "txn-already-in-mempool",
                },
                {
                    "txid": unprocessed.compute_txid().to_string(),
                    "wtxid": unprocessed.compute_wtxid().to_string(),
                },
            ])
        );
    }

    #[test]
    fn merkle_proof_round_trip_for_multiple_transactions() {
        let mut block = bitcoin::Block {
            header: Header {
                version: BlockVersion::TWO,
                prev_blockhash: BlockHash::all_zeros(),
                merkle_root: bitcoin::TxMerkleNode::all_zeros(),
                time: 1,
                bits: bitcoin::pow::CompactTarget::from_consensus(0x207f_ffff),
                nonce: 0,
            },
            txdata: vec![
                proof_transaction(1),
                proof_transaction(2),
                proof_transaction(3),
            ],
        };
        block.header.merkle_root = block.compute_merkle_root().unwrap();
        let requested = vec![
            block.txdata[0].compute_txid(),
            block.txdata[2].compute_txid(),
        ];
        let proof = serialize_merkle_proof(&block, &requested).unwrap();
        let (_, matches, total) = parse_merkle_proof(&json!([hex::encode(proof)]))
            .unwrap()
            .unwrap();
        assert_eq!(total, block.txdata.len());
        assert_eq!(matches, requested,);
    }

    #[test]
    fn merkle_proof_rejects_a_modified_header() {
        let mut block = bitcoin::Block {
            header: Header {
                version: BlockVersion::TWO,
                prev_blockhash: BlockHash::all_zeros(),
                merkle_root: bitcoin::TxMerkleNode::all_zeros(),
                time: 1,
                bits: bitcoin::pow::CompactTarget::from_consensus(0x207f_ffff),
                nonce: 0,
            },
            txdata: vec![proof_transaction(4), proof_transaction(5)],
        };
        block.header.merkle_root = block.compute_merkle_root().unwrap();
        let txid = block.txdata[1].compute_txid();
        let mut proof = serialize_merkle_proof(&block, &[txid]).unwrap();
        proof[36] ^= 1;
        assert!(
            parse_merkle_proof(&json!([hex::encode(proof)]))
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn merkle_proof_rejects_core_excessive_transaction_counts() {
        let mut block = bitcoin::Block {
            header: Header {
                version: BlockVersion::TWO,
                prev_blockhash: BlockHash::all_zeros(),
                merkle_root: bitcoin::TxMerkleNode::all_zeros(),
                time: 1,
                bits: bitcoin::pow::CompactTarget::from_consensus(0x207f_ffff),
                nonce: 0,
            },
            txdata: vec![proof_transaction(9)],
        };
        block.header.merkle_root = block.compute_merkle_root().unwrap();
        let txid = block.txdata[0].compute_txid();
        let mut proof = serialize_merkle_proof(&block, &[txid]).unwrap();
        proof[80..84].copy_from_slice(
            &u32::try_from(MAX_MERKLE_PROOF_TRANSACTIONS + 1)
                .unwrap()
                .to_le_bytes(),
        );
        assert!(parse_merkle_proof(&json!([hex::encode(proof)])).is_err());
    }

    #[test]
    fn merkle_proof_can_validly_contain_no_matches() {
        let mut block = bitcoin::Block {
            header: Header {
                version: BlockVersion::TWO,
                prev_blockhash: BlockHash::all_zeros(),
                merkle_root: bitcoin::TxMerkleNode::all_zeros(),
                time: 1,
                bits: bitcoin::pow::CompactTarget::from_consensus(0x207f_ffff),
                nonce: 0,
            },
            txdata: vec![proof_transaction(6), proof_transaction(7)],
        };
        block.header.merkle_root = block.compute_merkle_root().unwrap();
        let proof = serialize_merkle_proof(&block, &[]).unwrap();
        let (_, matches, _) = parse_merkle_proof(&json!([hex::encode(proof)]))
            .unwrap()
            .unwrap();
        assert!(matches.is_empty());
    }

