        let after_tip = get_block_stats(&node, &json!([1])).unwrap_err();
        assert_eq!(
            after_tip.to_string(),
            "Target block height 1 after current tip 0"
        );
        assert_eq!(rpc_error(&after_tip)["code"], json!(-8));
        assert!(stats.get("size").is_none());
