        assert_eq!(stats["subsidy"], json!(5_000_000_000u64));
        assert_eq!(stats["totalfee"], json!(0));
        assert_eq!(stats["utxo_increase_actual"], json!(0));
        assert_eq!(stats["utxo_size_inc_actual"], json!(0));
